"""Insertion boundary regressions and patches generated by git."""

import shutil
import subprocess
from pathlib import Path

import pytest

from pg_maker.changes.apply import apply_patch, insert_text
from pg_maker.errors import PreconditionError, UnsupportedError
from pg_maker.storage import file_hash


@pytest.mark.parametrize("layout", ["compact", "expanded"])
def test_guc_table_boundaries_first_bottom_and_exact_golden(tmp_path, layout):
    fixtures = Path(__file__).parents[1] / "fixtures/guc"
    path = tmp_path / "guc_tables.c"
    shutil.copyfile(fixtures / (layout + ".c"), path)
    document = {
        "target_file": path.name,
        "input_sha256": file_hash(path),
        "modifications": [
            {
                "top": "struct config_" + kind + " ConfigureNames",
                "bot": "/* End-of-list marker */",
                "alignment": "bot",
                "txt": "\t/* maker " + kind + " insertion */",
                "expect_matches": 1,
            }
            for kind in ("bool", "int")
        ],
    }
    insert_text(tmp_path, document)
    assert path.read_bytes() == (fixtures / (layout + "-golden.c")).read_bytes()
    with pytest.raises(PreconditionError, match="hash"):
        insert_text(tmp_path, document)
    document.pop("input_sha256")
    with pytest.raises(PreconditionError, match="already present"):
        insert_text(tmp_path, document)


def git(root, *args):
    return subprocess.run(
        ["git", "-C", str(root), *args], check=True, capture_output=True, text=True
    ).stdout


@pytest.fixture
def repository(tmp_path):
    root = tmp_path / "repo"
    root.mkdir()
    git(root, "init", "-q")
    git(root, "config", "user.name", "Fixture")
    git(root, "config", "user.email", "fixture@example.invalid")
    (root / "existing").write_text("old\n")
    (root / "remove").write_text("deleted\n")
    (root / "empty-remove").touch()
    git(root, "add", ".")
    git(root, "commit", "-qm", "base")
    target = tmp_path / "target"
    shutil.copytree(root, target, ignore=shutil.ignore_patterns(".git"))
    return root, target


@pytest.mark.parametrize("mail", [False, True])
def test_git_generated_patch_add_delete_executable_empty_and_mail(repository, mail):
    root, target = repository
    (root / "existing").write_text("new\n")
    (root / "remove").unlink()
    (root / "empty-remove").unlink()
    (root / "empty-add").touch()
    (root / "executable").write_text("#!/bin/sh\nexit 0\n")
    (root / "executable").chmod(0o755)
    git(root, "add", "-A")
    patch = git(root, "diff", "--cached", "--no-renames")
    if mail:
        git(root, "commit", "-qm", "change\n\nA real mail patch.")
        patch = git(root, "format-patch", "-1", "--stdout", "--no-renames")
    apply_patch(target, patch)
    assert {p.name for p in target.iterdir()} == {"existing", "empty-add", "executable"}
    assert (target / "existing").read_text() == "new\n"
    assert (target / "executable").stat().st_mode & 0o777 == 0o755


@pytest.mark.parametrize("kind", ["binary", "rename", "mode", "symlink"])
def test_git_generated_unsupported_changes(repository, kind):
    root, target = repository
    if kind == "binary":
        (root / "binary").write_bytes(b"\x00\x01\x02")
    elif kind == "rename":
        (root / "existing").rename(root / "renamed")
    elif kind == "mode":
        (root / "existing").chmod(0o755)
    else:
        (root / "link").symlink_to("existing")
    git(root, "add", "-A")
    with pytest.raises(UnsupportedError):
        apply_patch(target, git(root, "diff", "--cached", "--binary"))


def test_resolved_commit_does_not_apply_archive_attributes(repository, tmp_path):
    from pg_maker.sources.resolver import SourceResolver
    from pg_maker.sources.store import InputStore

    root, _ = repository
    (root / ".gitattributes").write_text(
        "hidden export-ignore\nversion export-subst\nnested/** export-ignore\n"
    )
    (root / "hidden").write_text("tracked input\n")
    (root / "version").write_text("$Format:%H$\n")
    (root / "nested").mkdir()
    (root / "nested/file").write_text("nested input\n")
    git(root, "add", ".")
    git(root, "commit", "-qm", "archive attributes")
    store = InputStore(tmp_path / "store")
    resolved = SourceResolver(store, tmp_path / "resolve").resolve(
        {"kind": "git", "repository": str(root), "ref": "HEAD"}, tmp_path
    )
    snapshot = store.tree(resolved["source_hash"])
    assert (snapshot / "hidden").read_text() == "tracked input\n"
    assert (snapshot / "version").read_text() == "$Format:%H$\n"
    assert (snapshot / "nested/file").read_text() == "nested input\n"
